class Solution:
    def minOperations(self, nums: list[int]) -> int:
        seen = set()
        j = 0
        for i in range(len(nums) - 1, -1, -1):
            if nums[i] in seen:
                j = i + 1
                break
            seen.add(nums[i])
        return (j + 2) // 3

