class Solution {
public:
    int minOperations(vector<int>& nums) {
        unordered_set<int> seen;
        int j = 0;
        for (int i = (int)nums.size() - 1; i >= 0; i--) {
            if (seen.count(nums[i])) { j = i + 1; break; }
            seen.insert(nums[i]);
        }
        return (j + 2) / 3;
    }
};

