    int minOperations(vector<int>& nums) {
        int ops = 0, start = 0;
        while (true) {
            unordered_set<int> st(nums.begin() + start, nums.end());
            if ((int)st.size() == (int)nums.size() - start) return ops;
            start += 3; ops++;
        }
    }
};

