class Solution {
    public int minOperations(int[] nums) {
        int ops = 0, start = 0;
        while (true) {
            Set<Integer> st = new HashSet<>();
            for (int i = start; i < nums.length; i++) st.add(nums[i]);
            if (st.size() == nums.length - start) return ops;
            start += 3; ops++;
        }
    }
}

